import { STREAM_MODES } from "./shared/api-contracts.js";
const EMULATOR_SERIAL = /^emulator-(\d+)$/;
export function parseEmulatorSerial(serial) {
    const match = serial.match(EMULATOR_SERIAL);
    return match ? {
        consolePort: match[1]
    } : null;
}
export function isEmulatorSerial(serial) {
    return parseEmulatorSerial(serial) !== null;
}
export function availableStreamModesForSerial(serial) {
    return isEmulatorSerial(serial) ? [
        ...STREAM_MODES
    ] : [
        "scrcpy"
    ];
}
